function OrderModal({ open, onClose, vendor }) {
  const [step, setStep] = useState("inventory");
  const [cart, setCart] = useState([]);
  const [slot, setSlot] = useState(null);

  useEffect(() => {
    if (open) { setStep("inventory"); setCart([]); setSlot(null); }
  }, [open]);

  if (!open || !vendor) return null;

  const add = (p) => setCart((c) => c.some((i) => i.id === p.id)
    ? c.map((i) => (i.id === p.id ? { ...i, qty: i.qty + 1 } : i))
    : [...c, { ...p, qty: 1 }]);
  const inc = (id) => setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: i.qty + 1 } : i)));
  const dec = (id) => setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: i.qty - 1 } : i)).filter((i) => i.qty > 0));
  const count = cart.reduce((n, i) => n + i.qty, 0);
  const total = cart.reduce((n, i) => n + i.price * i.qty, 0);

  const titles = { inventory: vendor.name, calendar: "Pick a time", done: "You're all set" };

  return (
    <div className="om-overlay" onClick={onClose}>
      <div className="om-sheet" role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
        <div className="om-head">
          <span className="om-grip" aria-hidden />
          <div className="om-head-row">
            {step === "calendar"
              ? <button className="om-icon" onClick={() => setStep("inventory")} aria-label="Back">←</button>
              : <span className="om-icon-sp" />}
            <h3 className="om-title">{titles[step]}</h3>
            <button className="om-icon" onClick={onClose} aria-label="Close">✕</button>
          </div>
        </div>

        <div className="om-body">
          {step === "inventory" && (
            <ul className="om-list">
              {vendor.menu.map((p) => {
                const inC = cart.find((i) => i.id === p.name);
                return (
                  <li key={p.name} className="om-item">
                    <span className="om-item-ico" aria-hidden>{p.icon}</span>
                    <div className="om-item-info">
                      <p className="om-item-name">{p.name}</p>
                      <p className="om-item-price">${p.price.toFixed(2)}</p>
                    </div>
                    {inC ? (
                      <div className="om-qty">
                        <button onClick={() => dec(p.name)} aria-label="Remove one">−</button>
                        <span>{inC.qty}</span>
                        <button onClick={() => inc(p.name)} aria-label="Add one">+</button>
                      </div>
                    ) : (
                      <button className="om-add" onClick={() => add({ id: p.name, name: p.name, price: p.price, icon: p.icon })}>Add</button>
                    )}
                  </li>
                );
              })}
            </ul>
          )}

          {step === "calendar" && (
            <div className="om-cal">
              <p className="om-pickup">Pickup at <b>{vendor.locName}</b></p>
              {ORDER_SLOTS.map((d) => (
                <div key={d.day}>
                  <p className="om-cal-day">{d.day}</p>
                  <div className="om-cal-grid">
                    {d.times.map((t) => {
                      const id = d.day + "|" + t.t;
                      return (
                        <button key={id} disabled={t.full}
                          className={"om-slot" + (t.full ? " full" : "") + (slot === id ? " on" : "")}
                          onClick={() => setSlot(id)}>{t.t}</button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}

          {step === "done" && (
            <div className="om-done">
              <div className="om-done-check" aria-hidden>✓</div>
              <h4>Order placed <span className="om-demo">demo</span></h4>
              <p className="om-done-sub">Pickup at <b>{vendor.locName}</b>{slot ? " · " + slot.split("|")[0] + " " + slot.split("|")[1] : ""}</p>
              <div className="om-receipt">
                {cart.map((i) => (
                  <div key={i.id} className="om-receipt-row"><span>{i.qty}× {i.name}</span><span>${(i.price * i.qty).toFixed(2)}</span></div>
                ))}
                <div className="om-receipt-total"><span>Total</span><span>${total.toFixed(2)}</span></div>
              </div>
              <p className="om-done-note">Payment would process securely through <b>{vendor.provider}</b>.</p>
            </div>
          )}
        </div>

        <div className="om-foot">
          {step === "inventory" && (
            <button className="om-cta" disabled={count === 0} onClick={() => setStep("calendar")}>
              {count > 0 && <span className="om-badge">{count}</span>}View Cart{count > 0 ? " · $" + total.toFixed(2) : ""}
            </button>
          )}
          {step === "calendar" && (
            <button className="om-cta" disabled={!slot} onClick={() => setStep("done")}>Secure Payment · ${total.toFixed(2)}</button>
          )}
          {step === "done" && (
            <button className="om-cta" onClick={onClose}>Done</button>
          )}
        </div>
      </div>
    </div>
  );
}

